import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"The lay of the land","description":"","frontmatter":{},"headers":[],"relativePath":"docs/science/topography.md","filePath":"docs/science/topography.md"}`),a={name:`docs/science/topography.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-lay-of-the-land" tabindex="-1">The lay of the land <a class="header-anchor" href="#the-lay-of-the-land" aria-label="Permalink to “The lay of the land”">​</a></h1><h2 id="the-sealed-truth" tabindex="-1">The Sealed Truth <a class="header-anchor" href="#the-sealed-truth" aria-label="Permalink to “The Sealed Truth”">​</a></h2><p><strong>Theorem:</strong> <code>Topography.lean</code> (0 theorems, all <code>by decide</code>)</p><p>topography as decidable arithmetic, the map beneath navigation — a contour joins points of equal height and every fifth line is the heavy index contour (multiples of 50 m at a 10 m interval), so elevation is read by COUNTING rings (5 × 20 = 100 m of ascent); gradient is rise over run (a 1-in-20 slope climbs 5 m in 100), contour spacing is its inverse (a steep 1-in-5 crowds the lines to 50 m, a gentle 1-in-10 spreads them to 100), and the slope distance is Pythagorean (a 400 m run up 300 m walks 500 m, longer than the map&#39;s flat shadow); scale is a pure ratio (1:25000 → 1 cm is 250 m, 4 cm a kilometre); a grid reference nests by tens (each 100 m square split ten ways to 10 m); a back-bearing is the forward turned 180° about the compass in ℤ/360; relief is the highest spot height less the lowest; Gunter&#39;s chain measures the mile and the acre whole (80 × 66 = 5280 ft, 22 × 220 = 4840 sq yd); triangulation rests on the 180° triangle; and a cross-section&#39;s vertical exaggeration stretches the slopes (500/100 = 5-fold). HONEST SCOPE: the arithmetic of the map — exact ratios, counts and cycles — NOT a survey, a GPS fix, or a route plan; the ledger seals only exact rational facts (the 3-4-5 slope triple, not a general hillside&#39;s irrational length), and Naismith&#39;s walking time is a rule-of-thumb ESTIMATE, demarcated and never staked on for safety</p><p><strong>Why sealed:</strong> Pure decidable arithmetic. No paradox, no experiment needed — the mathematics as recomputable facts.</p><hr><h2 id="the-honest-boundary" tabindex="-1">The Honest Boundary <a class="header-anchor" href="#the-honest-boundary" aria-label="Permalink to “The Honest Boundary”">​</a></h2><p><strong>What this CANNOT prove:</strong></p><ul><li>Whether the mechanism explains the phenomenon</li><li>Why humans find this beautiful, important, or meaningful</li><li>Whether the future will follow the same rules</li><li>What the universe &quot;should&quot; do</li></ul><p><strong>Honest scope:</strong> This theorem seals STRUCTURE. It does NOT settle meaning, purpose, or consequence.</p><hr><h2 id="the-metaphysical-pair" tabindex="-1">The Metaphysical Pair <a class="header-anchor" href="#the-metaphysical-pair" aria-label="Permalink to “The Metaphysical Pair”">​</a></h2><p><strong>The Question:</strong> <em>Is the landscape real or just elevation data?</em></p><p><strong>The Trinity:</strong></p><table tabindex="0"><thead><tr><th>Perspective</th><th>What It Proves</th><th>What It Cannot</th></tr></thead><tbody><tr><td><strong>Decidable (Sealed)</strong></td><td>[The sealed mathematics is exact and recomputable.]</td><td>Whether this mechanism is &quot;all there is&quot;; whether understanding it diminishes wonder; whether meaning requires non-mechanism</td></tr><tr><td><strong>Honest Boundary</strong></td><td>Understanding the structure does NOT negate the phenomenon. Both truth and beauty are real simultaneously.</td><td>Whether reduction to mechanism makes something &quot;less real&quot; or &quot;less meaningful&quot;; whether your experience is diminished by knowing its basis</td></tr><tr><td><strong>Metaphysical</strong></td><td>[The open question posed above.]</td><td>Whether the universe cares about this; whether your existence or choice matters; whether meaning requires transcendence</td></tr></tbody></table><p><strong>The court decides:</strong> This theorem seals the mechanism. Philosophy settles the meaning.</p><hr><h2 id="read-the-sealed-proof" tabindex="-1">Read the Sealed Proof <a class="header-anchor" href="#read-the-sealed-proof" aria-label="Permalink to “Read the Sealed Proof”">​</a></h2><p><a href="./../../lean/Topography.lean"><code>Topography.lean</code></a></p><p>Each theorem proven <code>by decide</code> — recompute it yourself.</p><hr><h2 id="the-research-question" tabindex="-1">The Research Question <a class="header-anchor" href="#the-research-question" aria-label="Permalink to “The Research Question”">​</a></h2><p>[Open question for you to explore. This is where inquiry begins.]</p><p><strong>These are open.</strong> Mathematics does not answer them. Philosophy, art, and human judgment do.</p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};